import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';

const html=readFileSync(new URL('./index.html',import.meta.url),'utf8');

test('background was upgraded without rebuilding the game',()=>{
  assert.doesNotMatch(html,/background:\s*#f2f2f2/i);
  assert.match(html,/(radial-gradient|linear-gradient)/i);
  for(const marker of ['SHADOW_PIECE_LOGIC_V1','drawShadowPiece','movePiece','rotatePiece','hardDrop','ArrowLeft','ArrowRight']) assert.match(html,new RegExp(marker));
  assert.match(html,/id="board"[^>]*width="300"[^>]*height="600"/);
  assert.match(html,/SHADOW TETRIS/);
});
